




"use strict";

const makeSerializable = require("../util/makeSerializable");
const ModuleDependency = require("./ModuleDependency");










class CssImportDependency extends ModuleDependency {
	











	constructor(
		request,
		range,
		mode,
		layer,
		supports,
		media,
		inheritance,
		exportType
	) {
		super(request);
		this.range = range;
		this.mode = mode;
		
		this.layer = layer;
		
		this.supports = supports;
		
		this.media = media;
		
		this.inheritance = inheritance;
		
		this.exportType = exportType;
	}

	get type() {
		return "css @import";
	}

	get category() {
		return `css-import${this.mode ? `-${this.mode}-module` : ""}`;
	}

	



	canConcatenate() {
		return true;
	}

	



	getResourceIdentifier() {
		let str = `context${this._context || ""}|module${this.request}`;

		if (this.mode) {
			str += `|mode${this.mode}`;
		}

		if (this.layer) {
			str += `|layer${this.layer}`;
		}

		if (this.supports) {
			str += `|supports${this.supports}`;
		}

		if (this.media) {
			str += `|media${this.media}`;
		}

		return str;
	}

	



	serialize(context) {
		const { write } = context;
		write(this.range);
		write(this.mode);
		write(this.layer);
		write(this.supports);
		write(this.media);
		write(this.inheritance);
		write(this.exportType);
		super.serialize(context);
	}

	



	deserialize(context) {
		const { read } = context;
		this.range = read();
		this.mode = read();
		this.layer = read();
		this.supports = read();
		this.media = read();
		this.inheritance = read();
		this.exportType = read();
		super.deserialize(context);
	}
}

CssImportDependency.Template = class CssImportDependencyTemplate extends (
	ModuleDependency.Template
) {
	






	apply(dependency, source, templateContext) {
		if (templateContext.type === "javascript") return;
		const dep =  (dependency);

		source.replace(dep.range[0], dep.range[1] - 1, "");
	}
};

makeSerializable(
	CssImportDependency,
	"webpack/lib/dependencies/CssImportDependency"
);

module.exports = CssImportDependency;
